$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$launcher=Join-Path $PSScriptRoot 'run_local.ps1';$runRoot=Join-Path $root 'logs/rsl_rl/unitree_b2w_stair';$outDir=Join-Path $root 'logs/stair_wheel_head_only_20260923';$bench=Join-Path $root 'logs/stair_benchmark';New-Item -ItemType Directory -Force $outDir|Out-Null;$jobs=@()
foreach($seed in @(54,55)){$runLabel="stair_wheel_head_only_2048_20260923_seed${seed}_full";$runs=@(Get-ChildItem $runRoot -Directory|Where-Object{$_.Name.EndsWith("_$runLabel")});if($runs.Count-ne1){throw "Run lookup failed"};$cp=Join-Path $runs[0].FullName 'model_422.pt';$m=Get-Content (Join-Path $runs[0].FullName 'stair_parent.json') -Raw|ConvertFrom-Json;if($m.actor_observation_dim-ne57-or-not$m.wheel_head_only){throw "Invalid manifest"};$label="wheel_head_only_s${seed}_v3open128";if(Get-ChildItem $bench -Filter "${label}_cycle_*.json" -ErrorAction SilentlyContinue){throw "Output exists"};$stdout=Join-Path $outDir "${label}.suite.stdout.log";$stderr=Join-Path $outDir "${label}.suite.stderr.log";$cli=@('-NoProfile','-ExecutionPolicy','Bypass','-File',('"'+$launcher+'"'),'scripts/eval_stair_suite.py','--checkpoint',('"'+$cp+'"'),'--label',$label,'--config','configs/stair_eval_v3.json','--split','development','--num-envs','128','--horizon','900','--brake-profile','--brake-distance','1.2','--brake-min-speed','0.25');$p=Start-Process powershell.exe -ArgumentList $cli -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$jobs += [pscustomobject]@{Label=$label;Process=$p};Write-Output "START $label PID=$($p.Id) actor=57"}
foreach($j in $jobs){$j.Process.WaitForExit();$j.Process.Refresh();$files=@(Get-ChildItem $bench -Filter "$($j.Label)_cycle_*.json");if($j.Process.ExitCode-ne0-or$files.Count-ne6){throw "Suite failed"};$r=@($files|ForEach-Object{Get-Content $_.FullName -Raw|ConvertFrom-Json});Write-Output "DONE $($j.Label) passage=$(($r|Measure-Object passage_success -Sum).Sum)/768 cycle=$(($r|Measure-Object success -Sum).Sum)/768 unsafe=$(($r|Measure-Object unsafe -Sum).Sum) stop_failed=$(($r|Measure-Object stop_failed -Sum).Sum) incomplete=$(($r|Measure-Object incomplete -Sum).Sum)"}
